#include "os.h"
#include "html.h"
/* Textbrowser: Darstellung und Bedienung. Das Parsen steckt in html.c, das Laden in http.c */
#define HMAX (4*1024*1024)
#define NH 24
#define UL 1200
#define VL 128
#define MAXF 256
typedef struct { hpage g; char*html; int hlen,lat,plain,top,sel,wid,state; char url[UL]; char msg[80]; char (*hist)[UL]; int htop[NH],nh; char (*val)[VL]; u8 *edit; int num; } web_t;
enum { ST_NEW,ST_SAFE,ST_PLAIN,ST_ERR };
static web_t*cur; static win_t*curw;
static const char START_EN[]="<title>Violyx Internet</title><h1>Violyx Internet</h1><p>Welcome to the text browser.</p><h2>Keys</h2><ul><li>Arrows and Page Up/Down scroll</li><li>Tab jumps to the next link, Shift+Tab back</li><li>Enter opens the link</li><li>Backspace goes back one page</li><li>Ctrl+L opens the address bar</li><li>N shows link numbers, number and Enter opens directly</li><li>Enter in search fields opens the input</li><li>Ctrl+R reloads, Ctrl+S saves the page</li><li>Esc closes the window</li></ul><h2>Try it</h2><ul><li><a href=\"https://en.wikipedia.org/\">Wikipedia</a></li><li><a href=\"https://lite.duckduckgo.com/lite/\">DuckDuckGo search</a></li><li><a href=\"https://de.wikipedia.org/\">Wikipedia (German)</a></li><li><a href=\"https://text.npr.org/\">NPR Text</a></li><li><a href=\"https://lite.cnn.com/\">CNN Lite</a></li><li><a href=\"https://lobste.rs/\">Lobsters</a></li><li><a href=\"https://example.com/\">example.com</a></li></ul><p>Please do not enter passwords here. Violyx is a hobby system without memory protection.</p>";
static const char START[]="<title>Violyx Internet</title><h1>Violyx Internet</h1><p>Willkommen im Textbrowser.</p><h2>Tasten</h2><ul><li>Pfeile und Bild auf/ab scrollen</li><li>Tab springt zum nächsten Link, Umschalt+Tab zurück</li><li>Enter öffnet den Link</li><li>Rücktaste geht eine Seite zurück</li><li>Strg+L öffnet die Adresszeile</li><li>N zeigt Link-Nummern, Zahl und Enter öffnet direkt</li><li>Enter in Suchfeldern öffnet die Eingabe</li><li>Strg+R lädt neu, Strg+S speichert die Seite</li><li>Esc schließt das Fenster</li></ul><h2>Zum Ausprobieren</h2><ul><li><a href=\"https://de.wikipedia.org/\">Wikipedia</a></li><li><a href=\"https://lite.duckduckgo.com/lite/\">DuckDuckGo Suche</a></li><li><a href=\"https://en.wikipedia.org/\">Wikipedia (Englisch)</a></li><li><a href=\"https://text.npr.org/\">NPR Text</a></li><li><a href=\"https://lite.cnn.com/\">CNN Lite</a></li><li><a href=\"https://lobste.rs/\">Lobsters</a></li><li><a href=\"https://example.com/\">example.com</a></li></ul><p>Bitte gib hier keine Passwörter ein. Violyx ist ein Hobbysystem ohne Speicherschutz.</p>";
static void layout(web_t*b,int w){ b->wid=w; html_lang=cfg_lang; html_layout(b->html,b->hlen,w,b->lat,b->plain,&b->g); }
static void relay(web_t*b,int w){ u32 off=b->top<b->g.nl?b->g.l[b->top].off:0; int oldnl=b->g.nl; layout(b,w); if(oldnl){ b->top=(int)((u64)b->top*b->g.nl/oldnl); } (void)off; if(b->top>=b->g.nl)b->top=b->g.nl?b->g.nl-1:0; b->sel=-1; }
static void prog(const char*t){ strlcpy_(cur->msg,t,80); ui_render(); ui_show(); }
static void setpage(web_t*b,const char*src,int n,int w){ memcpy(b->html,src,n); b->html[n]=0; b->hlen=n; b->lat=0;b->plain=0;b->top=0;b->sel=-1; layout(b,w); }
static void errpage(web_t*b,const char*t,const char*d,int w){ static char e[512]; int n=ksnprintf(e,512,"<title>%s</title><h1>%s</h1><p>%s</p>",t,t,d); if(n>511)n=511; setpage(b,e,n,w); }
static const char*frag(const char*u){ const char*h=strchr(u,'#'); return h?h+1:0; }
static void jump(web_t*b,const char*f,int view){ if(!f||!*f)return; u32 h=html_hash(f); for(int i=0;i<b->g.nan;i++) if(b->g.anch[i].h==h){ b->top=b->g.anch[i].line; if(b->top>=b->g.nl)b->top=b->g.nl?b->g.nl-1:0; return; } }
static int has(const char*s,const char*n){ size_t l=strlen(n); for(;*s;s++){ size_t i=0; for(;i<l;i++){ char c=s[i]; if(c>='A'&&c<='Z')c+=32; if(c!=n[i])break; } if(i==l)return 1; } return 0; }
static void load(win_t*w,web_t*b,const char*url,int push,int top,const char*post){ static char u[UL]; strlcpy_(u,url,UL); if(push&&b->url[0]){ if(b->nh==NH){ memmove(b->hist[0],b->hist[1],(NH-1)*UL); memmove(b->htop,b->htop+1,(NH-1)*sizeof(int)); b->nh--; } strlcpy_(b->hist[b->nh],b->url,UL); b->htop[b->nh]=b->top; b->nh++; }
  cur=b;curw=w; static http_res r; int wd=cw(w); int n=http_get(u,post,b->html,HMAX,&r,prog); memset(b->edit,0,MAXF); b->num=0; b->msg[0]=0; strlcpy_(b->url,r.final_url[0]?r.final_url:u,UL); if(frag(u)&&!frag(b->url)){ size_t l=strlen(b->url); if(l+strlen(frag(u))+2<UL){ b->url[l]='#'; strlcpy_(b->url+l+1,frag(u),UL-l-1); } }
  if(n<0){ b->state=ST_ERR; if(r.cert_bad)errpage(b,TR("Verbindung abgelehnt","Connection refused"),r.err,wd); else errpage(b,TR("Seite nicht geladen","Page not loaded"),r.err,wd); return; }
  b->state=r.tls?ST_SAFE:ST_PLAIN; int text=has(r.type,"text/plain"),html=has(r.type,"html")||!r.type[0]; if(!text&&!html){ static char m[120]; ksnprintf(m,120,TR("Dateityp nicht anzeigbar: %s","Cannot display file type: %s"),r.type); errpage(b,TR("Keine Textseite","Not a text page"),m,wd); return; }
  b->hlen=n; b->plain=text; b->lat=has(r.type,"8859")||has(r.type,"1252")||has(r.type,"latin"); if(!r.type[0]||!has(r.type,"charset")){ char sv=n>1024?b->html[1024]:0; if(n>1024)b->html[1024]=0; if(has(b->html,"charset=iso-8859")||has(b->html,"charset=\"iso-8859")||has(b->html,"windows-1252"))b->lat=1; if(n>1024)b->html[1024]=sv; }
  b->top=0;b->sel=-1; layout(b,wd); if(top)b->top=top<b->g.nl?top:0; else jump(b,frag(u),0); if(r.truncated)strlcpy_(b->msg,TR("Seite gekürzt: Größenlimit oder Verbindung abgebrochen","Page truncated: size limit or connection lost"),80); else if(b->g.full)strlcpy_(b->msg,TR("Seite zu lang, Ende nicht dargestellt","Page too long, end not shown"),80); else if(r.status>=400)ksnprintf(b->msg,80,TR("Server meldet Fehler %d","Server reported error %d"),r.status); }
static void w_draw(win_t*w){ web_t*b=w->st; if(b->wid!=cw(w))relay(b,cw(w)); int H_=ch(w)-2,W_=cw(w); hpage*g=&b->g; u8 bg=C_PANEL; cfill(w,AT(bg,C_LAV));
  static const u8 sa[]={AT(C_PANEL,C_LAV),AT(C_PANEL,C_NEON),AT(C_PANEL,C_GLOW),AT(C_PANEL,C_HOT),AT(C_PANEL,C_MID),AT(C_PANEL,C_VIOLET),AT(C_VOID,C_GLOW)};
  for(int x=0;x<W_;x++){ cput(w,x,0,' ',AT(C_RAISE,C_LAV)); cput(w,x,ch(w)-1,' ',AT(C_RAISE,C_LAV)); }
  const char*lab=b->state==ST_SAFE?TR(" Sicher "," Secure "):b->state==ST_PLAIN?TR(" UNVERSCHLÜSSELT "," NOT ENCRYPTED "):b->state==ST_ERR?TR(" Fehler "," Error "):" Violyx "; u8 la=b->state==ST_SAFE?AT(C_SEL,C_GLOW):b->state==ST_NEW?AT(C_RAISE,C_NEON):AT(C_HOT,C_VOID); ctext(w,0,0,la,lab); int lx=0; for(const char*p=lab;*p;p++) if((*p&0xC0)!=0x80)lx++; lx++; char u[100]; strlcpy_(u,b->url,W_-lx>98?99:W_-lx+1); int k=0; for(;u[k]&&lx+k<W_;k++)cput(w,lx+k,0,(u8)u[k],AT(C_RAISE,C_LAV));
  for(int y=0;y<H_;y++){ int i=b->top+y; if(i>=g->nl)break; hline*l=&g->l[i]; int fi=0; u16 fl=0; for(int x=0;x<l->len&&x<W_;x++){ u32 o=l->off+x; u16 lk=g->lk[o]; u8 a=(b->sel>=0&&lk==b->sel+1)?AT(C_SEL,C_GLOW):sa[g->st[o]]; u8 c=g->ch[o]; if(lk&&c=='_'&&g->st[o]==HS_FIELD&&g->links[lk-1].field>=0){ if(fl!=lk){ fl=lk; fi=0; } int f=g->links[lk-1].field; const char*v=f<MAXF&&b->edit[f]?b->val[f]:g->pool+g->fld[f].value; int n=strlen(v); int c2=g->fld[f].cols,s0=n>c2?n-c2:0; c=fi<n-s0?(u8)v[s0+fi]:(u8)' '; fi++; } cput(w,x,y+1,c,a); } }
  char f[130]; f[0]=0; if(b->msg[0])strlcpy_(f,b->msg,130); else if(b->num)ksnprintf(f,130,TR("Link %d, Enter öffnet","Link %d, Enter opens"),b->num); else if(b->sel>=0&&b->sel<g->nlk){ int fd=g->links[b->sel].field; if(fd>=0)strlcpy_(f,g->fld[fd].type==HF_TEXT?TR("Eingabefeld: Enter zum Ausfüllen","Input field: press Enter to fill in"):TR("Knopf: Enter sendet das Formular","Button: press Enter to submit"),130); else strlcpy_(f,g->pool+g->links[b->sel].off,130); } else strlcpy_(f,TR("Tab Link   N Nummern   Enter Öffnen   Rücktaste Zurück   Strg+L Adresse","Tab Link   N Numbers   Enter Open   Backspace Back   Ctrl+L Address"),130); if((int)strlen(f)>W_)f[W_]=0; ctext(w,0,ch(w)-1,AT(C_RAISE,C_LAV),f);
  int pct=g->nl>H_?(b->top*100)/(g->nl-H_>0?g->nl-H_:1):100; if(pct>100)pct=100; ksnprintf(w->foot,64," %d / %d (%d%%) ",b->top+1,g->nl,pct); win_title(w,g->title[0]?g->title:"Violyx Internet"); }
static int enc(char*o,int p,int max,const char*v,int cp){ for(;*v;v++){ u8 c=*v; u8 t[4]; int n=1; t[0]=c; if(cp&&c>=0x80){ u16 u=html_cp437_uni(c); if(u<0x800){ t[0]=0xC0|u>>6; t[1]=0x80|(u&63); n=2; } else { t[0]=0xE0|u>>12; t[1]=0x80|((u>>6)&63); t[2]=0x80|(u&63); n=3; } } for(int i=0;i<n;i++){ c=t[i]; if(p+4>=max)return -1; if((c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||c=='-'||c=='_'||c=='.'||c=='~')o[p++]=c; else if(c==' ')o[p++]='+'; else { o[p++]='%'; o[p++]="0123456789ABCDEF"[c>>4]; o[p++]="0123456789ABCDEF"[c&15]; } } } o[p]=0; return p; }
static void submit(win_t*w,web_t*b,int form,int btn){ hpage*g=&b->g; static char q[1300],url[UL],ful[UL]; int p=0; for(int i=0;i<g->nf;i++){ hfield*f=&g->fld[i]; if(f->form!=form)continue; if(f->type==HF_SUBMIT&&i!=btn)continue; const char*nm=g->pool+f->name; if(!*nm)continue; int ed=i<MAXF&&b->edit[i]; if(p){ if(p+2>=1300)goto big; q[p++]='&'; } p=enc(q,p,1300,nm,0); if(p<0||p+2>=1300)goto big; q[p++]='='; q[p]=0; p=enc(q,p,1300,ed?b->val[i]:g->pool+f->value,ed); if(p<0)goto big; }
  if(html_resolve(b->url[0]?b->url:"https://violyx.invalid/",g->pool+g->frm[form].action,url,UL)){ strlcpy_(b->msg,TR("Formularziel nicht unterstützt","Form target not supported"),80); return; } { char*h=strchr(url,'#'); if(h)*h=0; }
  if(g->frm[form].post){ load(w,b,url,1,0,q); return; } { char*h=strchr(url,'?'); if(h)*h=0; } if(ksnprintf(ful,UL,"%s?%s",url,q)>=UL)goto big; load(w,b,ful,1,0,0); return;
  big: strlcpy_(b->msg,TR("Formular zu groß","Form too large"),80); }
static void openlink(win_t*w,web_t*b,int id){ hpage*g=&b->g; static char in[UL]; int f=g->links[id].field; if(f>=0){ hfield*fd=&g->fld[f]; if(fd->type==HF_SUBMIT){ submit(w,b,fd->form,f); return; } if(f>=MAXF)return; static char v[VL]; strlcpy_(v,b->edit[f]?b->val[f]:g->pool+fd->value,VL); if(dlg_input(TR("Eingabe","Input"),TR("Text eingeben:","Enter text:"),v,VL)){ strlcpy_(b->val[f],v,VL); b->edit[f]=1; int tx=0; for(int i=0;i<g->nf;i++) if(g->fld[i].form==fd->form&&g->fld[i].type==HF_TEXT)tx++; if(tx==1)submit(w,b,fd->form,-1); } else if(!v[0]){ b->val[f][0]=0; b->edit[f]=1; } return; }
  const char*r=g->pool+g->links[id].off; if(r[0]=='#'){ jump(b,r+1,0); b->sel=-1; return; } if(html_resolve(b->url[0]?b->url:"https://violyx.invalid/",r,in,UL)){ strlcpy_(b->msg,TR("Dieser Linktyp wird nicht unterstützt","This link type is not supported"),80); return; } load(w,b,in,1,0,0); }
static void clamp(web_t*b,int h){ int m=b->g.nl-h; if(b->top>m)b->top=m; if(b->top<0)b->top=0; }
static void w_key(win_t*w,key_t k){ web_t*b=w->st; hpage*g=&b->g; int h=ch(w)-2; static char in[UL];
  if(k.mods&M_CTRL){ if(k.key=='l'){ strlcpy_(in,b->url,UL); dlg_fresh=1; if(dlg_input(TR("Adresse","Address"),TR("Adresse eingeben:","Enter address:"),in,600))load(w,b,in,1,0,0); return; } if(k.key=='s'){ char n[VFS_PATH],p[VFS_PATH]; const char*t=b->url; for(const char*q=b->url;*q&&*q!='?'&&*q!='#';q++) if(*q=='/'&&q[1]&&q[1]!='?')t=q+1; int l=0; ksnprintf(n,VFS_PATH,"%s/",fs_ok()?"/downloads":fsx_home()); l=strlen(n); while(*t&&*t!='?'&&*t!='#'&&*t!='/'&&l<60)n[l++]=*t++; n[l]=0; if(l<=11)strlcpy_(n,"/downloads/page.html",VFS_PATH); if(dlg_input(TR("Seite speichern","Save page"),TR("Pfad und Dateiname:","Path and file name:"),n,VFS_PATH-1)){ if(vfs_norm("/downloads",n,p,VFS_PATH))return; int r=fsx_write(p,b->html,b->hlen,fs_now()); strlcpy_(b->msg,r?vfs_errstr(r,cfg_lang):TR("Gespeichert","Saved"),80); } return; } if(k.key=='r'){ if(b->url[0]){ strlcpy_(in,b->url,UL); load(w,b,in,0,b->top,0); } return; } if(k.key==K_HOME)b->top=0; else if(k.key==K_END)b->top=g->nl; clamp(b,h); return; }
  switch(k.key){ case K_UP:b->top--;break; case K_DOWN:b->top++;break; case K_PGUP:b->top-=h-1;break; case K_PGDN:case ' ':b->top+=h-1;break; case K_HOME:b->top=0;break; case K_END:b->top=g->nl;break;
   case K_TAB:{ int vis=b->sel>=0&&g->links[b->sel].line>=b->top&&g->links[b->sel].line<b->top+h; int back=k.mods&M_SHIFT,i; if(back){ i=vis?b->sel-1:g->nlk-1; if(!vis)while(i>=0&&g->links[i].line>=b->top+h)i--; while(i>=0&&g->links[i].line<0)i--; } else { i=vis?b->sel+1:0; if(!vis)while(i<g->nlk&&g->links[i].line<b->top)i++; while(i<g->nlk&&g->links[i].line<0)i++; if(i>=g->nlk)i=-1; } if(i>=0){ b->sel=i; int l=g->links[i].line; if(l<b->top)b->top=l; if(l>=b->top+h)b->top=l-h/2; } b->msg[0]=0; break; }
   case K_ENTER: b->msg[0]=0; if(b->num){ int n=b->num-1; b->num=0; if(n<g->nlk&&n>=0){ b->sel=n; openlink(w,b,n); } else strlcpy_(b->msg,TR("Diese Nummer gibt es nicht","No such number"),80); return; } if(b->sel>=0&&b->sel<g->nlk){ openlink(w,b,b->sel); return; } break;
   case K_BS: if(b->nh){ b->nh--; strlcpy_(in,b->hist[b->nh],UL); load(w,b,in,0,b->htop[b->nh],0); return; } else strlcpy_(b->msg,TR("Keine vorherige Seite","No previous page"),80); break;
   case 'n': case 'N': g->nums=!g->nums; b->num=0; b->wid=0; return;
   default: if(k.key>='0'&&k.key<='9'&&g->nums){ if(b->num<10000)b->num=b->num*10+k.key-'0'; } return; }
  clamp(b,h); }
static void w_free(win_t*w){ web_t*b=w->st; hpage*g=&b->g; kfree(g->l);kfree(g->ch);kfree(g->st);kfree(g->lk);kfree(g->pool);kfree(g->links);kfree(g->anch);kfree(g->fld);kfree(g->frm);kfree(b->val);kfree(b->edit);kfree(b->html);kfree(b->hist);kfree(b); }
static const app_t web_app={w_draw,w_key,0,0,w_free};
void app_web(void){ web_app_open(0); }
void web_app_open(const char*url){ web_t*b=kmalloc(sizeof*b); if(!b)return; memset(b,0,sizeof*b); hpage*g=&b->g; g->maxl=120000;g->cap=2000000;g->pc=1024*1024;g->maxlk=20000;g->maxan=8192; g->l=kmalloc(sizeof(hline)*g->maxl);g->ch=kmalloc(g->cap);g->st=kmalloc(g->cap);g->lk=kmalloc(g->cap*2);g->pool=kmalloc(g->pc);g->links=kmalloc(sizeof(hlink)*g->maxlk);g->anch=kmalloc(sizeof(hanchor)*g->maxan);g->maxf=MAXF;g->maxfrm=64;g->fld=kmalloc(sizeof(hfield)*g->maxf);g->frm=kmalloc(sizeof(hform)*g->maxfrm);b->val=kmalloc(MAXF*VL);b->edit=kmalloc(MAXF);if(b->edit)memset(b->edit,0,MAXF);b->html=kmalloc(HMAX+1);b->hist=kmalloc(NH*UL);
  if(!g->fld||!g->frm||!b->val||!b->edit||!g->l||!g->ch||!g->st||!g->lk||!g->pool||!g->links||!g->anch||!b->html||!b->hist){ dlg_msg("Internet",TR("Nicht genug Arbeitsspeicher.","Not enough memory.")); kfree(g->l);kfree(g->ch);kfree(g->st);kfree(g->lk);kfree(g->pool);kfree(g->links);kfree(g->anch);kfree(g->fld);kfree(g->frm);kfree(b->val);kfree(b->edit);kfree(b->html);kfree(b->hist);kfree(b); return; }
  win_t*w=win_open("Violyx Internet",1,1,78,23,&web_app,b); if(!w){ kfree(g->l);kfree(g->ch);kfree(g->st);kfree(g->lk);kfree(g->pool);kfree(g->links);kfree(g->anch);kfree(g->fld);kfree(g->frm);kfree(b->val);kfree(b->edit);kfree(b->html);kfree(b->hist);kfree(b); return; } win_zoom(w); if(cfg_lang)setpage(b,START_EN,sizeof START_EN-1,cw(w)); else setpage(b,START,sizeof START-1,cw(w)); if(url)load(w,b,url,0,0,0); }
